// Mock CMS service for the user‑portal project
// This file provides a minimal implementation of the `getPostSummaries` function
// referenced in `src/pages/index.tsx`. It returns a static list of blog post
// summaries so the page can render without requiring a real backend.

export interface BlogPostSummary {
  id: string;
  title: string;
  excerpt: string;
  slug: string;
  date: string; // ISO string
}

/**
 * Returns a static array of blog post summaries.
 * In a real application this would fetch data from a headless CMS or API.
 */
export async function getPostSummaries(): Promise<BlogPostSummary[]> {
  // Simulated delay to mimic a network request (optional)
  await new Promise((resolve) => setTimeout(resolve, 100));

  return [
    {
      id: '1',
      title: 'Welcome to the CABI Blog',
      excerpt: 'An introduction to our new blog platform and upcoming content.',
      slug: 'welcome-to-cabi-blog',
      date: new Date().toISOString(),
    },
    {
      id: '2',
      title: 'Advances in Agricultural Research',
      excerpt: 'A look at recent breakthroughs in sustainable farming practices.',
      slug: 'advances-in-agricultural-research',
      date: new Date().toISOString(),
    },
    {
      id: '3',
      title: 'Tech Innovations for Climate Resilience',
      excerpt: 'How technology is helping farmers adapt to climate change.',
      slug: 'tech-innovations-climate-resilience',
      date: new Date().toISOString(),
    },
  ];
}
