// apps/user-portal/src/components/PostSummaryCard.tsx
import Image from 'next/image';
import Link from 'next/link';
import type { BlogPostSummary } from '@/backend/services/cms';

export default function PostSummaryCard({
    post,
}: {
    post: BlogPostSummary;
}) {
    return (
        <Link href={`/posts/${post.id}`} className="group relative flex flex-col bg-white dark:bg-slate-800 rounded-2xl overflow-hidden shadow-sm hover:shadow-xl transition-all duration-300 transform hover:-translate-y-1">
            <div className="relative aspect-video w-full overflow-hidden bg-slate-100 dark:bg-slate-700">
                {/* Generic Gradient Placeholder since we have no real images yet */}
                <div className="absolute inset-0 bg-gradient-to-br from-blue-500 to-purple-600 opacity-80 group-hover:scale-105 transition-transform duration-500" />
                <div className="absolute inset-0 flex items-center justify-center text-white/90 font-medium text-lg">
                    {post.title.substring(0, 1)}
                </div>
            </div>

            <div className="flex flex-col flex-1 p-6">
                <div className="flex items-center gap-2 mb-3">
                    <span className="text-xs font-semibold px-2.5 py-0.5 rounded-full bg-indigo-100 text-indigo-800 dark:bg-indigo-900/50 dark:text-indigo-300">
                        Article
                    </span>
                    <span className="text-xs text-slate-500 dark:text-slate-400">
                        {new Date(post.date).toLocaleDateString('en-US', { month: 'long', day: 'numeric', year: 'numeric' })}
                    </span>
                </div>

                <h3 className="text-xl font-bold text-slate-900 dark:text-white mb-3 line-clamp-2 group-hover:text-indigo-600 dark:group-hover:text-indigo-400 transition-colors">
                    {post.title}
                </h3>

                <p className="text-base text-slate-600 dark:text-slate-300 line-clamp-3 mb-4 flex-1">
                    {post.excerpt}
                </p>

                <div className="flex items-center text-sm font-medium text-indigo-600 dark:text-indigo-400 group-hover:translate-x-1 transition-transform">
                    Read article <span className="ml-1">→</span>
                </div>
            </div>
        </Link>
    );
}
